<template><div class="page"><div class="page-head"><div><h1 class="page-title">公告管理</h1><div class="page-sub">发布开放时间、活动和重要通知</div></div><el-button type="primary" @click="open()"><el-icon><Plus/></el-icon>发布公告</el-button></div><div class="notice-grid"><el-card v-for="n in rows" :key="n.id"><div class="notice-head"><el-tag :type="n.type==='IMPORTANT'?'danger':'success'">{{n.type==='IMPORTANT'?'重要':'通知'}}</el-tag><el-dropdown><el-button text><el-icon><MoreFilled/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="open(n)">编辑</el-dropdown-item><el-dropdown-item @click="remove(n.id)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><h3>{{n.title}}</h3><p>{{n.content}}</p><small>{{n.publishTime?.replace('T',' ')}}</small></el-card></div><el-dialog v-model="visible" :title="form.id?'编辑公告':'发布公告'" width="580"><el-form label-position="top"><el-form-item label="公告标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="公告类型"><el-radio-group v-model="form.type"><el-radio value="NOTICE">普通通知</el-radio><el-radio value="IMPORTANT">重要公告</el-radio></el-radio-group></el-form-item><el-form-item label="公告内容"><el-input type="textarea" :rows="6" v-model="form.content"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">发布</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),visible=ref(false),form=reactive<any>({});onMounted(load);async function load(){rows.value=await api.get('/api/system/announcements')}function open(r:any={}){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r,{type:r.type||'NOTICE',priority:r.priority||0,publisherId:1});visible.value=true}async function save(){form.id?await api.put(`/api/system/announcements/${form.id}`,form):await api.post('/api/system/announcements',form);ElMessage.success('发布成功');visible.value=false;load()}async function remove(id:number){await api.delete(`/api/system/announcements/${id}`);load()}</script><style scoped>.notice-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.notice-head{display:flex;justify-content:space-between}.notice-grid h3{font-size:17px}.notice-grid p{color:#6d7d90;line-height:1.8;height:58px;overflow:hidden}.notice-grid small{color:#a5afbb}@media(max-width:900px){.notice-grid{grid-template-columns:1fr}}</style>

